const fs = require('node:fs');
const saToken = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
if (!saToken) {
  throw new Error('ServiceAccount token file is empty');
}
return [{ json: { sa_token: saToken } }];

// Daily consent-expiry check (spec 005 §4.2.1).
// Inputs are the two fullResponse HTTP nodes (body + statusCode on $json.x);
// the n8n Code sandbox forbids network modules, so the network itself is done
// by HTTP Request nodes (Read ServiceAccount -> Get Stable Secret -> Get Token
// Secret). A 404 on the token Secret means "no tokens yet"; anything else
// non-200 is thrown so the error workflow reports it.
const stableGet = $('Get Stable Secret').first().json;
if (stableGet.statusCode !== 200) {
  throw new Error(
    `finance-enablebanking unreadable (HTTP ${stableGet.statusCode}); check RoleBinding n8n-finance-secrets`
  );
}
const accounts = JSON.parse(Buffer.from(stableGet.body.data['accounts.json'], 'base64').toString());

const tokenGet = $('Get Token Secret').first().json;
let tokensByAlias = {};
if (tokenGet.statusCode === 404) {
  tokensByAlias = {};
} else if (tokenGet.statusCode === 200) {
  const raw = (tokenGet.body.data || {})['tokens.json'];
  tokensByAlias = raw ? JSON.parse(Buffer.from(raw, 'base64').toString()) : {};
} else {
  throw new Error(`finance-enablebanking-token GET returned HTTP ${tokenGet.statusCode}`);
}

const due = [];
for (const [alias, cfg] of Object.entries(accounts)) {
  const entry = tokensByAlias[alias];
  const until = entry ? entry.valid_until : null;
  const days = until ? Math.floor((new Date(until) - Date.now()) / 86400000) : -1;
  if (days <= 3) {
    const when = until ? new Date(until).toISOString().slice(0, 10) : 'no token yet';
    due.push(`- *${alias}* (${cfg.institution_id || alias}): expires on ${when}`);
  }
}
const needsRenewal = due.length > 0;
return [
  {
    json: {
      needs_renewal: needsRenewal,
      nudge_text: needsRenewal
        ? `Enable Banking consent expiring:\n${due.join('\n')}\n\nRenew now (the bank login is the one manual step): https://automation-n8n.homelab.alvsanand.com/form/7c1f51ab-5f61-4b21-9b31-01befd1d0d02`
        : 'all consents healthy',
    },
  },
];

const fs = require('node:fs');
const saToken = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
if (!saToken) {
  throw new Error('ServiceAccount token file is empty');
}
return [{ json: { sa_token: saToken } }];

// Form branch: mint the RS256 JWT and return the request body for POST /auth.
// $json comes from the fullResponse "Get Stable Secret - Form" HTTP node, and
// the alias is the form's "Account alias" field. No network here - the HTTP
// node "Post /auth" sends what this returns.
const crypto = require('node:crypto');

const stableGet = $('Get Stable Secret - Form').first().json;
if (stableGet.statusCode !== 200) {
  throw new Error(`finance-enablebanking unreadable (HTTP ${stableGet.statusCode}); check RoleBinding n8n-finance-secrets`);
}
const accounts = JSON.parse(Buffer.from(stableGet.body.data['accounts.json'], 'base64').toString());
const alias = $('Form: Start Renewal').first().json['Account alias'];
const config = accounts[alias];
if (!config) {
  throw new Error(`unknown alias '${alias}'; configured: ${Object.keys(accounts).join(', ')}`);
}
if (!config.app_id) {
  throw new Error(`alias '${alias}' has no app_id in finance-enablebanking`);
}
const pem = Buffer.from(stableGet.body.data['private_key'], 'base64').toString();
const issuedAt = Math.floor(Date.now() / 1000);
const head = Buffer.from(JSON.stringify({ typ: 'JWT', alg: 'RS256', kid: config.app_id })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  iss: 'enablebanking.com',
  aud: 'api.enablebanking.com',
  iat: issuedAt,
  exp: issuedAt + 3600,
})).toString('base64url');
const signer = crypto.createSign('RSA-SHA256');
signer.update(`${head}.${payload}`);
signer.end();
const jwt = `${head}.${payload}.${signer.sign(pem).toString('base64url')}`;
return [
  {
    json: {
      jwt,
      auth_body: JSON.stringify({
        access: { valid_until: new Date(Date.now() + 180 * 86400000).toISOString() },
        aspsp: { name: config.institution_id || alias, country: 'ES' },
        state: crypto.randomUUID(),
        redirect_url: 'https://automation-n8n.homelab.alvsanand.com/webhook/enablebanking-consent',
        psu_type: 'personal',
      }),
    },
  },
];

const fs = require('node:fs');
const saToken = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
if (!saToken) {
  throw new Error('ServiceAccount token file is empty');
}
return [{ json: { sa_token: saToken } }];

// Webhook branch: mint the exchange JWT (RS256, kid = the single application's
// app_id) and the POST /sessions body. The consent code comes from the bank's
// redirect (?code=). The exchange JWT's kid must be the application that
// started the consent - one application per fleet today; a second application
// needs the alias tracked through the consent state first.
const crypto = require('node:crypto');

const code = $('EnableBanking Redirect').first().json.query.code;
const stableGet = $('Get Stable Secret - Webhook').first().json;
if (stableGet.statusCode !== 200) {
  throw new Error(`finance-enablebanking unreadable (HTTP ${stableGet.statusCode}); check RoleBinding n8n-finance-secrets`);
}
const accounts = JSON.parse(Buffer.from(stableGet.body.data['accounts.json'], 'base64').toString());
const firstAlias = Object.keys(accounts)[0];
if (!firstAlias) {
  throw new Error('finance-enablebanking accounts.json is empty');
}
const app_id = accounts[firstAlias].app_id;
const pem = Buffer.from(stableGet.body.data['private_key'], 'base64').toString();
const issuedAt = Math.floor(Date.now() / 1000);
const head = Buffer.from(JSON.stringify({ typ: 'JWT', alg: 'RS256', kid: app_id })).toString('base64url');
const payload = Buffer.from(JSON.stringify({
  iss: 'enablebanking.com',
  aud: 'api.enablebanking.com',
  iat: issuedAt,
  exp: issuedAt + 3600,
})).toString('base64url');
const signer = crypto.createSign('RSA-SHA256');
signer.update(`${head}.${payload}`);
signer.end();
const jwt = `${head}.${payload}.${signer.sign(pem).toString('base64url')}`;
return [
  {
    json: {
      jwt,
      session_body: JSON.stringify({ code }),
    },
  },
];

// Merge the fresh session material per alias and build the token Secret body.
// $json = the fullResponse "Post /sessions" item; the existing tokens come from
// the neverError "Get Token Secret" HTTP item (404 -> renewal-owned Secret is
// absent; the following IF routes create vs replace).
const sessionGet = $('Post /sessions').first().json;
if (sessionGet.statusCode !== 200) {
  throw new Error(`POST /sessions failed (HTTP ${sessionGet.statusCode}): ${JSON.stringify(sessionGet.body).slice(0, 200)}`);
}
const session = sessionGet.body;
const validUntil = (session.access || {}).valid_until;
if (!validUntil) {
  throw new Error(`session response carried no access.valid_until: ${JSON.stringify(session).slice(0, 200)}`);
}

const tokenGet = $('Get Token Secret - Webhook').first().json;
let tokens = {};
let tokenSecretExisted = false;
if (tokenGet.statusCode === 404) {
  tokenSecretExisted = false;
} else if (tokenGet.statusCode === 200) {
  const raw = (tokenGet.body.data || {})['tokens.json'];
  tokens = raw ? JSON.parse(Buffer.from(raw, 'base64').toString()) : {};
  tokenSecretExisted = true;
} else {
  throw new Error(`finance-enablebanking-token GET returned HTTP ${tokenGet.statusCode}`);
}

const stableGet = $('Get Stable Secret - Webhook').first().json;
const accounts = JSON.parse(Buffer.from(stableGet.body.data['accounts.json'], 'base64').toString());

const renewals = [];
for (const resource of session.accounts || []) {
  if (!resource.uid) continue;
  const iban = (resource.account_id || {}).iban;
  const matched = Object.entries(accounts).filter(([, cfg]) => cfg.iban === iban);
  const alias = matched.length ? matched[0][0] : null;
  if (!alias) {
    throw new Error(
      `session account ****${String(iban).slice(-4)} is not in finance-enablebanking accounts.json; add its alias first`
    );
  }
  tokens[alias] = { uid: resource.uid, valid_until: validUntil };
  renewals.push(alias);
}
if (renewals.length === 0) {
  throw new Error('Enable Banking session authorized zero accounts; nothing to store');
}

const secretBody = {
  apiVersion: 'v1',
  kind: 'Secret',
  metadata: { name: 'finance-enablebanking-token', namespace: 'data' },
  data: { 'tokens.json': Buffer.from(JSON.stringify(tokens)).toString('base64') },
};
return [
  {
    json: {
      token_secret_missing: !tokenSecretExisted,
      secret_body: JSON.stringify(secretBody),
      slack_text: `Enable Banking token renewed for ${renewals.join(', ')}: consent valid until `
        + `${new Date(validUntil).toISOString().slice(0, 10)}. The daily pipeline picks it up on the next run.`,
    },
  },
];

